// Build-time interlock between the recognizer frontend compiled here and the packaged model.
//
// A model's int8 calibration is only valid for the frontend it was exported with. The device
// compares the model file's header with identity::kFrontendSha at load time
// (stt_model_container.h), but that only proves the file matches the identity header; it does not
// prove the identity header matches quartznet_frontend.cpp. Without this file, firmware computing
// log(mel + 2^-30) rows would still accept a model packed for the 2^-24 contract.
//
// quartznet_frontend_contract.h is generated by tools/stt_p4/frontend/contract.py from the hashed
// frontend sources. To fix a failure here, install the stt_model_identity.h of a package packed with
// --frontend-sha256 equal to tools/stt_p4/frontend/frontend-contract.json's SHA-256 (and point
// kModelPath at its .p4.stt), or rerun contract.py after an intended frontend change and repack.
// See docs/STT_FRONTEND_GUARD.md. No code is generated; this translation unit is empty.
#include "quartznet_frontend.h"
#include "quartznet_frontend_contract.h"
#include "stt_model_identity.h"

namespace hw1::stt {
namespace {
constexpr bool same_sha(const std::uint8_t (&a)[32], const std::uint8_t (&b)[32]) {
    for (int i = 0; i < 32; ++i)
        if (a[i] != b[i]) return false;
    return true;
}
static_assert(frontend_contract::kLogGuard == kLogGuard,
              "quartznet_frontend.h kLogGuard differs from quartznet_frontend_contract.h: rerun "
              "tools/stt_p4/frontend/contract.py, then re-export and repack the model");
static_assert(same_sha(identity::kFrontendSha, frontend_contract::kSha),
              "stt_model_identity.h was packed for a different recognizer frontend contract: install the "
              "identity header (and kModelPath) of a package packed for this tree's frontend-contract.json "
              "(docs/STT_FRONTEND_GUARD.md)");
}  // namespace
}  // namespace hw1::stt
